const cfg = $('Ajustes').first().json;
const fotos = ($input.first().json.momentos || []).slice().sort((a, b) => new Date(a.ts) - new Date(b.ts));
return fotos.map(f => {
  const hora = new Date(f.ts).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Madrid' });
  const nota = (f.nota || '').trim().replace(/\s+/g, ' ');
  return { json: { url: f.url, variable: nota ? `${nota} (${hora})` : `(${hora})`, phone_number_id: cfg.phone_number_id, to: cfg.to, template: cfg.template, lang: cfg.lang } };
});
